// Each purchasable type has its own ID so carts, QRIS amounts and receipts
// always use the price of the type explicitly selected by the visitor.
export const offers = products.flatMap(product => product.variants
  ? product.variants.map(variant => ({...product,...variant,productId:product.id,name:`${product.name} — ${variant.label}`}))
  : [{...product,productId:product.id}]);
